public class Eq {
    // returns which element is added: "COMPACT", "GENERIC", or "NONE"
    static String original(boolean g, boolean c) {
        String added = "NONE";
        if (g && c) { added = "COMPACT"; }
        if (!g) {
            if (c) { added = "COMPACT"; }
            else { added = "GENERIC"; }
        }
        return added;
